Define cumulative fluxes
\begin{equation}
 q_0=0,\qquad
 q_j=\sum_{i=1}^{j}p_i\quad(1\leq j\leq N),
 \label{found:q-definition}
\end{equation}
and the right-continuous step function
\begin{equation}
 F(x)=\sum_{j=1}^{N}p_j\mathbf1_{\{x_j\leq x\}}.
 \label{found:F-definition}
\end{equation}
Explicitly,
\[
 F(x)=
 \begin{cases}
 0,&0\leq x<x_1,\\
 q_1,&x_1\leq x<x_2,\\
 q_2,&x_2\leq x<x_3,\\
 \vdots&\\
 q_N,&x_N\leq x\leq1.
 \end{cases}
\]

\subsubsection{The fundamental theorem of calculus}

\paragraph{Fundamental theorem of calculus (quoted elementary theorem).}
If $g$ is continuous on $[a,b]$ and
\[
 G(x)=\int_a^x g(s)\,\mathrm ds,
\]
then $G'(x)=g(x)$ and
\begin{equation}
 \int_a^b g(s)\,\mathrm ds=G(b)-G(a).
 \label{found:ftc}
\end{equation}
Thus integrating a derivative recovers the change in the original function:
\begin{equation}
 \int_a^b f'(x)\,\mathrm dx=f(b)-f(a).
 \label{found:integrate-derivative}
\end{equation}
We repeatedly use this formula on each open interval between neighboring
traps.

\subsubsection{Integration by parts}

\paragraph{Integration by parts (quoted elementary theorem).}
For continuously differentiable $f$ and $g$,
\begin{equation}
 \int_a^b f'(x)g(x)\,\mathrm dx
 =f(b)g(b)-f(a)g(a)-\int_a^b f(x)g'(x)\,\mathrm dx.
 \label{found:ibp-first}
\end{equation}
Applying this with $f=u'$ and multiplying by $-D$ gives the form used later:
\begin{align}
 \int_a^b -D u''(x)v(x)\,\mathrm dx
 &=-D\bigl[u'(x)v(x)\bigr]_{a}^{b}
   +D\int_a^b u'(x)v'(x)\,\mathrm dx \notag\\
 &=D\int_a^b u'v'\,\mathrm dx
   -Du'(b)v(b)+Du'(a)v(a).
 \label{found:ibp-second}
\end{align}
The boundary signs in \eqref{found:ibp-second} determine the signs in the
point-trap jump conditions.

\subsection{Chain rule, inverse derivative, and substitution}

\begin{toolbox}{chain rule}
If $U(y)$ is evaluated at $y=P(x)$, then
\[
\frac{\dd}{\dd x}U(P(x))=U'(P(x))P'(x).
\]
\end{toolbox}

\subsubsection{The chain rule}

\paragraph{Chain rule (quoted elementary theorem).}
If $y=P(x)$ and $U$ is differentiable, then
\begin{equation}
 \frac{\mathrm d}{\mathrm dx}U(P(x))
 =U'(P(x))P'(x).
 \label{found:chain-rule}
\end{equation}
Later we set $u(x)=U(P(x))$. If $P'(x)=\pi(x)$, the chain rule gives
\begin{equation}
 u'(x)=U'(P(x))\pi(x).
 \label{found:chain-special}
\end{equation}
This factor of $\pi$ is important: losing it would give the wrong weight in
the generalized theorem.

\subsubsection{Changing variables in an integral}

\paragraph{One-dimensional substitution rule (quoted elementary theorem).}
Suppose $y=P(x)$ is continuously differentiable and strictly increasing.
Then $\mathrm dy=P'(x)\,\mathrm dx$, and
\begin{equation}
 \int_{x=a}^{x=b}h(P(x))P'(x)\,\mathrm dx
 =\int_{y=P(a)}^{y=P(b)}h(y)\,\mathrm dy.
 \label{found:substitution}
\end{equation}
Equivalently, if $X=P^{-1}$, then
\begin{equation}
 \mathrm dx=X'(y)\,\mathrm dy
 =\frac{1}{P'(X(y))}\,\mathrm dy.
 \label{found:inverse-substitution}
\end{equation}
The inverse-derivative identity follows by differentiating $P(X(y))=y$:
\[
 P'(X(y))X'(y)=1,
 \qquad
 X'(y)=\frac1{P'(X(y))}.
\]

\subsection{Completing a weighted square}

For positive numbers $\kappa_j$ with $\sum_j\kappa_j=K$ and numbers $p_j$
with $\sum_jp_j=1$,
\begin{align*}
\sum_{j=1}^{N}\frac{(p_j-\kappa_j/K)^2}{\kappa_j}
&=\sum_j\frac{p_j^2-2p_j\kappa_j/K+\kappa_j^2/K^2}{\kappa_j}\\
&=\sum_j\frac{p_j^2}{\kappa_j}
 -\frac2K\sum_jp_j+\frac1{K^2}\sum_j\kappa_j\\
&=\sum_j\frac{p_j^2}{\kappa_j}-\frac2K+\frac1K\\
&=\sum_j\frac{p_j^2}{\kappa_j}-\frac1K.
\end{align*}
Rearranging produces the exact identity
\[
\boxed{\displaystyle
\sum_j\frac{p_j^2}{\kappa_j}
=\frac1K+
\sum_j\frac{(p_j-\kappa_j/K)^2}{\kappa_j}.}
\]
Because every denominator is positive and every numerator is a square, the
second term is nonnegative.  Equality holds exactly when
$p_j=\kappa_j/K$ for every $j$.

Here ``admissible'' means continuous on the graph and $H^1$ on each edge.
The solution $u$ is the Poisson response.  Its maximum
\begin{equation}
 M:=\max_{x\in G}u(x)
 \label{eq:exp-x12-M}
\end{equation}
is the worst-start response.  The maximum exists because $G$ is compact and
$u$ is continuous.

\subsubsection{Taylor expansion and infinitesimal change}

\paragraph{Second-order Taylor formula (quoted elementary theorem).}
For a twice continuously differentiable function $f$ and a small increment
$h$,
\begin{equation}
 f(x+h)=f(x)+f'(x)h+\frac12f''(x)h^2+r(h),
 \qquad \frac{r(h)}{h^2}\longrightarrow0
 \quad(h\to0).
 \label{found:taylor}
\end{equation}
This explains why Brownian motion, whose displacement has mean zero but
variance proportional to time, produces a second derivative in its generator.

\subsubsection{The exponential distribution}

A unit exponential random variable $E$ is defined by its survival function
\begin{equation}
 \mathbb P(E>z)=e^{-z},\qquad z\geq0.
 \label{found:exp-survival}
\end{equation}
Its density is $e^{-z}$ on $z\geq0$, because
\[
 -\frac{\mathrm d}{\mathrm dz}\mathbb P(E>z)
 =-\frac{\mathrm d}{\mathrm dz}e^{-z}=e^{-z}.
\]
Its mean is one:
\begin{align*}
 \mathbb E[E]
 &=\int_0^\infty z e^{-z}\,\mathrm dz\\
 &=\bigl[-ze^{-z}\bigr]_{0}^{\infty}
   +\int_0^\infty e^{-z}\,\mathrm dz
 =0+1=1.
\end{align*}
The second line is integration by parts. The exponential threshold is used
because it converts accumulated hazard $A_t$ into the simple survival factor
$e^{-A_t}$.

\subsection{From local time to a random killing time}

Choose distinct interior points and positive strengths
\begin{equation}
 0<x_1<x_2<\cdots<x_N<1,
 \qquad \kappa_j>0,
 \qquad \sum_{j=1}^{N}\kappa_j=K.
 \label{found:design}
\end{equation}
The number $K>0$ is the total available reactivity. Define accumulated hazard
\begin{equation}
 A_t=\sum_{j=1}^{N}\kappa_j\ell_t^{x_j}.
 \label{found:hazard}
\end{equation}
Because every local time is nondecreasing in $t$, $A_t$ is nondecreasing.

Let $E$ be a unit exponential variable independent of the path and define
\begin{equation}
 \tau=\inf\{t\geq0:A_t\geq E\}.
 \label{found:killing-time}
\end{equation}
In words, the particle dies when accumulated hazard first crosses the random
threshold $E$.

Fix a path up to time $t$. Since $A$ is nondecreasing,
\[
 \{\tau>t\}=\{A_t<E\}=\{E>A_t\}.
\]
Independence of $E$ and the path and the exponential survival formula
\eqref{found:exp-survival} give
\begin{equation}
 \boxed{
 \mathbb P(\tau>t\mid X_s,\ 0\leq s\leq t)=e^{-A_t}.}
 \label{found:conditional-survival}
\end{equation}
This equation is derived directly from the definition of $\tau$.

\subsubsection{Expectation as an integral of survival probabilities}

\paragraph{Tail-integral formula (quoted probability theorem).}
For any nonnegative random variable $T$,
\begin{equation}
 \mathbb E[T]=\int_0^\infty \mathbb P(T>t)\,\mathrm dt,
 \label{found:tail-integral}
\end{equation}
where either side may initially be infinite.

For a fixed number $T\geq0$,
\[
 T=\int_0^\infty\mathbf 1_{\{t<T\}}\,\mathrm dt.
\]
Taking expectations and exchanging the two nonnegative integrations gives
\begin{align*}
 \mathbb E[T]
 &=\mathbb E\left[\int_0^\infty
   \mathbf 1_{\{t<T\}}\,\mathrm dt\right]\\
 &=\int_0^\infty\mathbb E[\mathbf 1_{\{t<T\}}]\,\mathrm dt\\
 &=\int_0^\infty\mathbb P(T>t)\,\mathrm dt.
\end{align*}
The theorem that justifies exchanging nonnegative integrals is Tonelli's
theorem, a standard result from measure theory.

Define the mean lifetime for a particle started at $x$ by
\begin{equation}
 u(x)=\mathbb E_x[\tau].
 \label{found:u-definition}
\end{equation}
Using the tail-integral formula, conditioning on the path, and
\eqref{found:conditional-survival},
\begin{align}
 u(x)
 &=\int_0^\infty\mathbb P_x(\tau>t)\,\mathrm dt \notag\\
 &=\int_0^\infty
   \mathbb E_x\!\left[
   \mathbb P(\tau>t\mid X_s,\ 0\leq s\leq t)
   \right]\mathrm dt \notag\\
 &=\int_0^\infty\mathbb E_x[e^{-A_t}]\,\mathrm dt \notag\\
 &=\boxed{\mathbb E_x\left[\int_0^\infty e^{-A_t}\,\mathrm dt\right]}.
 \label{found:feynman-kac-representation}
\end{align}
The final exchange is again Tonelli's theorem because the integrand is
nonnegative.

If the starting point is uniform on $[0,1]$, its expected lifetime is
\begin{equation}
 \overline u=\int_0^1u(x)\,\mathrm dx.
 \label{found:average-lifetime}

\subsection{Brownian motion and its reflected version}

\subsubsection{What Brownian motion means}

\paragraph{Definition (standard).}
A standard Brownian motion $W_t$ is a continuous random function of time with
$W_0=0$ such that increments over nonoverlapping time intervals are
independent and
\begin{equation}
 W_{t+h}-W_t\sim \mathcal N(0,h).
 \label{found:brownian-increment}
\end{equation}
The notation $\mathcal N(0,h)$ means a normal random variable with mean $0$
and variance $h$. Therefore
\begin{equation}
 \mathbb E[W_{t+h}-W_t]=0,
 \qquad
 \mathbb E[(W_{t+h}-W_t)^2]=h.
 \label{found:brownian-moments}
\end{equation}

For diffusivity $D>0$, free diffusion is
\begin{equation}
 X_{t+h}-X_t\approx\sqrt{2D}\,(W_{t+h}-W_t).
 \label{found:scaled-brownian}
\end{equation}
Consequently, over a short time $h$,
\begin{equation}
 \mathbb E[X_{t+h}-X_t]\approx0,
 \qquad
 \mathbb E[(X_{t+h}-X_t)^2]\approx2Dh.
 \label{found:scaled-moments}
\end{equation}
Diffusivity has units ``distance squared divided by time.''

\subsubsection{Why the generator is $D\partial_{xx}$}

The generator records expected change per unit time. For a smooth test
function $f$, its definition is
\begin{equation}
 Lf(x)=\lim_{h\downarrow0}
 \frac{\mathbb E_x[f(X_h)]-f(x)}{h},
 \label{found:generator-definition}
\end{equation}
provided the limit exists. Write $\Delta X=X_h-x$ and apply Taylor's formula:
\[
 f(x+\Delta X)-f(x)
 =f'(x)\Delta X+\frac12f''(x)(\Delta X)^2+r(\Delta X).
\]
Taking expectations and using \eqref{found:scaled-moments},
\begin{align*}
 \mathbb E_x[f(X_h)]-f(x)
 &=f'(x)\underbrace{\mathbb E[\Delta X]}_{=0}
   +\frac12f''(x)\underbrace{\mathbb E[(\Delta X)^2]}_{=2Dh}
   +o(h)\\
 &=Df''(x)h+o(h).
\end{align*}
Divide by $h$ and take $h\downarrow0$:
\begin{equation}
 \boxed{Lf=Df''.}
 \label{found:brownian-generator}
\end{equation}
This calculation is an explanation. A fully rigorous proof that Brownian
motion has this generator is a standard quoted theorem.

\subsubsection{Reflection at the endpoints}

Reflected Brownian motion on $[0,1]$ behaves like ordinary Brownian motion in
the interior and is pushed inward whenever it attempts to cross $0$ or $1$.
One rigorous construction solves the Skorokhod reflection equation
\begin{equation}
 X_t=X_0+\sqrt{2D}\,W_t+R_t^0-R_t^1,
 \label{found:skorokhod}
\end{equation}
where $R_t^0$ and $R_t^1$ are nondecreasing regulator processes. The process
$R^0$ grows only while $X_t=0$, and $R^1$ grows only while $X_t=1$. Thus
$R^0$ pushes to the right and $R^1$ pushes to the left.

\paragraph{Reflected-diffusion generator theorem (quoted).}
The reflected process \eqref{found:skorokhod} has generator $Lf=Df''$ in the
interior. The generator domain has Neumann conditions
\begin{equation}
 f'(0)=f'(1)=0.
 \label{found:neumann-test}
\end{equation}
A zero normal derivative means zero probability flux across a wall, which is
the differential-equation expression of reflection.

\subsubsection{The stationary distribution}

A stationary density is a probability density that does not change as the
process evolves. For constant-diffusivity reflected Brownian motion, it is
uniform:
\begin{equation}
 \pi(x)=1,\qquad 0\leq x\leq1.
 \label{found:uniform-stationary}
\end{equation}
It is normalized because $\int_0^1 1\,\mathrm dx=1$. At the
differential-equation level, stationary probability flux is proportional to
$-D\pi'(x)$, which vanishes because $\pi'=0$.

\subsection{Why point traps require local time}

\subsubsection{Ordinary time spent at a single point is zero}

A Brownian path visits points, but the ordinary amount of clock time spent at
one exact point is zero. Formally,
\[
 \int_0^t\mathbf 1_{\{X_s=x\}}\,\mathrm ds=0
\]
almost surely for fixed interior $x$. A killing rule based on ordinary time
at exactly $x$ would therefore do nothing. Local time is the correct
``magnified'' measure of repeated contact.

\subsubsection{Occupation-normalized local time}

\paragraph{Occupation-density theorem (quoted).}
For one-dimensional reflected Brownian motion, there is a family
$\ell_t^x$, called occupation-normalized local time, such that for every
bounded measurable function $f$,
\begin{equation}
 \boxed{
 \int_0^t f(X_s)\,\mathrm ds
 =\int_0^1 f(x)\ell_t^x\,\mathrm dx.}
 \label{found:occupation-formula}
\end{equation}
Thus $\ell_t^x$ is the density, with respect to position, of time spent by
the path.  This standard construction is treated in detail in
\cite{karatzas1991}.

An intuitive approximation follows by choosing a narrow interval around
$x$. Let
\[
 f_h(y)=\frac{1}{2h}\mathbf 1_{\{|y-x|<h\}}.
\]
Substitution into \eqref{found:occupation-formula} gives
\begin{equation}
 \frac1{2h}\int_0^t\mathbf 1_{\{|X_s-x|<h\}}\,\mathrm ds
 =\frac1{2h}\int_{x-h}^{x+h}\ell_t^y\,\mathrm dy.
 \label{found:band-local-time}
\end{equation}
If $y\mapsto\ell_t^y$ is continuous near $x$, the average on the right tends
to $\ell_t^x$ as $h\downarrow0$. Hence
\begin{equation}
 \ell_t^x
 =\lim_{h\downarrow0}\frac1{2h}
   \int_0^t\mathbf 1_{\{|X_s-x|<h\}}\,\mathrm ds.
 \label{found:local-time-limit}
\end{equation}
This is not time at the point. It is time in a thin band divided by the band
width before the width is sent to zero.

\subsubsection{Relation to semimartingale local time}

Some books use symmetric semimartingale local time $L_t^x$. Its occupation
formula is
\begin{equation}
 \int_0^t f(X_s)\,\mathrm d\langle X\rangle_s
 =\int_0^1 f(x)L_t^x\,\mathrm dx,
 \label{found:semi-occupation}
\end{equation}
where $\langle X\rangle_t$ is quadratic variation. For the diffusion part
$\sqrt{2D}\,W_t$,
\[
 \mathrm d\langle X\rangle_s=2D\,\mathrm ds.
\]
The left side of \eqref{found:semi-occupation} is therefore
$2D\int_0^t f(X_s)\,\mathrm ds$. Comparison with
\eqref{found:occupation-formula} yields
\begin{equation}
 \boxed{L_t^x=2D\ell_t^x,
 \qquad \ell_t^x=\frac{L_t^x}{2D}.}
 \label{found:local-time-normalization}
\end{equation}
This factor $2D$ is a convention, not a physical disagreement. A trap
strength must be rescaled if a different local-time convention is used.

A function $u$ is in the Sobolev space $H^1(0,1)$ if
\begin{equation}
 \int_0^1|u(x)|^2\,\mathrm dx<\infty,
 \qquad
 \int_0^1|u'(x)|^2\,\mathrm dx<\infty,
 \label{found:H1-definition}
\end{equation}
where $u'$ may be a weak derivative. Its norm is
\begin{equation}
 \|u\|_{H^1}^2=\int_0^1|u|^2\,\mathrm dx+
                    \int_0^1|u'|^2\,\mathrm dx.
 \label{found:H1-norm}
\end{equation}

\paragraph{One-dimensional Sobolev continuity theorem (quoted).}
Every $H^1(0,1)$ function has a continuous representative, and evaluation
$u\mapsto u(x_j)$ is a continuous linear operation. Thus $u(x_j)$ in the
point-trap equation is meaningful; see, for example, the Sobolev-space
chapters of \cite{evans2010}.

For intuition, an $H^1$ function obeys the fundamental-theorem identity
\[
 u(x)=u(z)+\int_z^xu'(s)\,\mathrm ds.
\]
The Cauchy--Schwarz inequality gives
\begin{align*}
 |u(x)-u(z)|
 &\leq\int_z^x|u'(s)|\,\mathrm ds\\
 &\leq |x-z|^{1/2}
 \left(\int_0^1|u'(s)|^2\,\mathrm ds\right)^{1/2}.
\end{align*}
This estimate explains why a finite-energy one-dimensional function cannot
jump.

\subsubsection{The second derivative of a function with slope jumps}

Suppose $u$ is continuous and twice differentiable away from the trap points.
Let
\begin{equation}
 [u']_{x_j}=u'(x_j+)-u'(x_j-)
 \label{found:jump-notation}
\end{equation}
denote the jump in slope. Its distributional second derivative is
\begin{equation}
 u''_{\mathrm{dist}}
 =u''_{\mathrm{classical}}+
   \sum_{j=1}^{N}[u']_{x_j}\delta_{x_j}.
 \label{found:distribution-second}
\end{equation}
Formula~\eqref{found:distribution-second} follows by integrating by parts
separately on the intervals cut out by the $x_j$. Endpoint terms at each
interior cut combine into the difference between right and left slopes.

\subsection{Reading the weak equation one term at a time}

The term
\[
 D\int_0^1u'v'\,\mathrm dx
\]
is diffusion energy. The term
\[
 \sum_j\kappa_ju(x_j)v(x_j)
\]
is the action of the atomic killing measure. The right side
$\int_0^1v\,\mathrm dx$ comes from the constant source $1$ in the mean-time
equation. The distributional shorthand is
\begin{equation}
 \boxed{
 -Du''(x)+\sum_{j=1}^{N}
 \kappa_ju(x_j)\delta_{x_j}(x)=1,}
 \qquad 0<x<1,
 \label{found:distribution-pde}
\end{equation}
with reflecting boundary conditions
\begin{equation}
 u'(0)=u'(1)=0.
 \label{found:neumann-u}
\end{equation}

The delta coefficient is $\kappa_ju(x_j)$, not merely $\kappa_j$. The point
interaction is proportional to the unknown lifetime at that trap. This makes
the later physical fluxes endogenous rather than freely chosen.

\subsubsection{Deriving the weak equation from the distributional equation}

Multiply \eqref{found:distribution-pde} by a test function $v$ and integrate:
\begin{align*}
 \int_0^1-Du''(x)v(x)\,\mathrm dx
 +\sum_{j=1}^{N}\kappa_ju(x_j)
   \int_0^1\delta_{x_j}(x)v(x)\,\mathrm dx
 =\int_0^1v(x)\,\mathrm dx.
\end{align*}
By the delta rule, the second term is
$\sum_j\kappa_ju(x_j)v(x_j)$. By integration by parts,
\begin{align*}
 \int_0^1-Du''v\,\mathrm dx
 &=D\int_0^1u'v'\,\mathrm dx
   -Du'(1)v(1)+Du'(0)v(0)\\
 &=D\int_0^1u'v'\,\mathrm dx,
\end{align*}
where the last equality uses $u'(0)=u'(1)=0$. This gives exactly
\eqref{found:weak-constant}.

\subsubsection{The ordinary equation between traps}

Strictly between traps every delta term vanishes, so
\begin{equation}
 -Du''(x)=1,
 \qquad
 u''(x)=-\frac1D.
 \label{found:between-traps}
\end{equation}
Integrating twice gives
\[
 u'(x)=-\frac{x}{D}+C_1
\]
and
\begin{equation}
 u(x)=-\frac{x^2}{2D}+C_1x+C_2
 \label{found:piecewise-quadratic}
\end{equation}
on each trap-free interval. Thus $u$ is piecewise quadratic.

\subsubsection{Deriving the slope jump at a trap}

Integrate \eqref{found:distribution-pde} from $x_j-\eta$ to $x_j+\eta$,
where the interval contains no other trap:
\begin{align*}
 -D\int_{x_j-\eta}^{x_j+\eta}u''(x)\,\mathrm dx
 +\kappa_ju(x_j)
 \int_{x_j-\eta}^{x_j+\eta}\delta_{x_j}(x)\,\mathrm dx
 =\int_{x_j-\eta}^{x_j+\eta}1\,\mathrm dx.
\end{align*}
Evaluate the integrals:
\[
 -D\bigl(u'(x_j+\eta)-u'(x_j-\eta)\bigr)
 +\kappa_ju(x_j)=2\eta.
\]
Let $\eta\downarrow0$ and rearrange:
\begin{equation}
 \boxed{
 D\bigl(u'(x_j+)-u'(x_j-)\bigr)=\kappa_ju(x_j).}
 \label{found:slope-jump}
\end{equation}
This fixes the sign: a positive trap produces an upward derivative jump.

In distributional notation, \eqref{found:general-weak} is
\begin{equation}
 -(a(x)u'(x))'
 +\sum_{j=1}^{N}\kappa_ju(x_j)\delta_{x_j}(x)
 =\pi(x),
 \label{found:general-distribution}
\end{equation}
with reflecting flux conditions
\begin{equation}
 a(0)u'(0)=a(1)u'(1)=0.
 \label{found:general-neumann}
\end{equation}
Integrating across $x_j$ gives
\begin{equation}
 (au')(x_j+)-(au')(x_j-)=\kappa_ju(x_j).
 \label{found:general-jump}
\end{equation}
If $a$ is continuous, this can also be written
$a(x_j)[u'(x_j+)-u'(x_j-)]=\kappa_ju(x_j)$.

\paragraph{General local-time Feynman--Kac theorem (quoted).}
With atomic Revuz-normalized killing at $x_j$, the mean lifetime is the unique
weak solution
\begin{equation}
 \boxed{
 \int_0^1a(x)u'(x)v'(x)\,\mathrm dx
 +\sum_{j=1}^{N}\kappa_ju(x_j)v(x_j)
 =\int_0^1\pi(x)v(x)\,\mathrm dx}
 \label{found:general-weak}
\end{equation}
for every $v\in H^1(0,1)$.  This is the symmetric-process
additive-functional Feynman--Kac framework of
\cite{fitzsimmons1999,fukushima2011}, specialized to finitely many atoms.

\subsubsection{Absorbed flux at each trap}

Define
\begin{equation}
 \boxed{p_j=\kappa_ju(x_j).}
 \label{found:p-definition}
\end{equation}
The jump condition becomes
\begin{equation}
 D[u']_{x_j}=p_j.
 \label{found:p-jump}
\end{equation}
Thus $p_j$ is the derivative-flux jump caused by trap $j$. Since
$\kappa_j>0$ and $u(x_j)>0$, we have $p_j>0$.

The $p_j$ are not independent design choices. The physical choices are
$x_j$ and $\kappa_j$; solving the full boundary-value problem determines
$u(x_j)$ and hence $p_j$. This is the meaning of \emph{endogenous flux}.

Define cumulative fluxes
\begin{equation}
 q_0=0,\qquad
 q_j=\sum_{i=1}^{j}p_i\quad(1\leq j\leq N),
 \label{found:q-definition}
\end{equation}
and the right-continuous step function
\begin{equation}
 F(x)=\sum_{j=1}^{N}p_j\mathbf1_{\{x_j\leq x\}}.
 \label{found:F-definition}
\end{equation}
Explicitly,
\[
 F(x)=
 \begin{cases}
 0,&0\leq x<x_1,\\
 q_1,&x_1\leq x<x_2,\\
 q_2,&x_2\leq x<x_3,\\
 \vdots&\\
 q_N,&x_N\leq x\leq1.
 \end{cases}
\]

\subsubsection{Why the fluxes add to one}

In \eqref{found:weak-constant}, choose $v(x)=1$. Then $v'=0$, so
\begin{align*}
 D\int_0^1u'(x)\underbrace{v'(x)}_{0}\,\mathrm dx
 +\sum_{j=1}^{N}\kappa_ju(x_j)\underbrace{v(x_j)}_{1}
 &=\int_0^1 1\,\mathrm dx,\\
 \sum_{j=1}^{N}p_j&=1.
\end{align*}
Therefore
\begin{equation}
 \boxed{\sum_{j=1}^{N}p_j=1,\qquad q_N=1.}
 \label{found:flux-conservation}
\end{equation}
The unit source must all be absorbed by the traps. Since every $p_j>0$ and
their sum is one, $(p_1,\ldots,p_N)$ is a probability vector.

\subsubsection{Deriving the exact flux law}

Rewrite the distributional PDE using $p_j$:
\begin{equation}
 -Du''(x)+\sum_{j=1}^{N}p_j\delta_{x_j}(x)=1.
 \label{found:p-pde}
\end{equation}
Integrate from $0$ to a non-trap point $x$:
\begin{align*}
 -D\int_0^xu''(s)\,\mathrm ds
 +\sum_{j=1}^{N}p_j\int_0^x\delta_{x_j}(s)\,\mathrm ds
 &=\int_0^x1\,\mathrm ds,\\
 -D\bigl(u'(x)-u'(0)\bigr)+\sum_{x_j\leq x}p_j&=x.
\end{align*}
Use $u'(0)=0$ and the definition of $F$:
\[
 -Du'(x)+F(x)=x.
\]
Rearranging gives
\begin{equation}
 \boxed{Du'(x)=F(x)-x}
 \qquad\text{for almost every }x\in(0,1).
 \label{found:constant-flux-law}
\end{equation}
At $x=1$, this gives
\[
 Du'(1)=F(1)-1=q_N-1=0,
\]
so right reflection is equivalent to total-flux conservation. The term $F(x)$
is cumulative absorbed flux to the left of $x$, while $x$ is source mass
generated by $[0,x]$. Their difference is the remaining diffusive flux.

\subsection{Flux variables in stationary coordinates}

Define
\begin{equation}
 p_j=\kappa_jU(y_j),\qquad
 q_0=0,\qquad
 q_j=\sum_{i=1}^{j}p_i,
 \label{found:general-pq}
\end{equation}
and
\begin{equation}
 F(y)=\sum_{j=1}^{N}p_j\mathbf1_{\{y_j\leq y\}}.
 \label{found:general-F}
\end{equation}
Set $V\equiv1$ in \eqref{found:transformed-weak}. Since $V'=0$,
\begin{equation}
 \sum_{j=1}^{N}p_j=1,\qquad q_N=1.
 \label{found:general-conservation}
\end{equation}

In distributions, \eqref{found:transformed-weak} reads
\begin{equation}
 -(b(y)U'(y))'
 +\sum_{j=1}^{N}p_j\delta_{y_j}(y)=1.
 \label{found:transformed-distribution}
\end{equation}
Integrate from $0$ to $y$:
\[
 -\bigl(b(y)U'(y)-b(0)U'(0)\bigr)+F(y)=y.
\]
The left reflecting condition is $b(0)U'(0)=0$, hence
\begin{equation}
 \boxed{b(y)U'(y)=F(y)-y.}
 \label{found:general-flux-law}
\end{equation}
Since $\omega=1/b$, this is equivalently
\begin{equation}
 \boxed{U'(y)=\omega(y)(F(y)-y).}
 \label{found:general-Uprime}

\subsubsection{Deriving the exact energy identity}

Choose $v=u$ in the weak equation:
\begin{equation}
 D\int_0^1|u'(x)|^2\,\mathrm dx
 +\sum_{j=1}^{N}\kappa_ju(x_j)^2
 =\int_0^1u(x)\,\mathrm dx=\overline u.
 \label{found:test-u}
\end{equation}
We simplify the two terms separately. The flux law gives
\[
 u'(x)=\frac{F(x)-x}{D},
\]
and hence
\begin{align*}
 D\int_0^1|u'|^2\,\mathrm dx
 &=D\int_0^1\left(\frac{F(x)-x}{D}\right)^2\mathrm dx\\
 &=\frac1D\int_0^1(F(x)-x)^2\,\mathrm dx.
\end{align*}
Also, $p_j=\kappa_ju(x_j)$ gives $u(x_j)=p_j/\kappa_j$, so
\[
 \kappa_ju(x_j)^2
 =\kappa_j\left(\frac{p_j}{\kappa_j}\right)^2
 =\frac{p_j^2}{\kappa_j}.
\]
Substitution into \eqref{found:test-u} proves
\begin{equation}
 \boxed{
 \overline u
 =\sum_{j=1}^{N}\frac{p_j^2}{\kappa_j}
 +\frac1D\int_0^1(F(x)-x)^2\,\mathrm dx.}
 \label{found:constant-energy}
\end{equation}
The first term penalizes a mismatch between trap strength and absorbed flux.
The second measures the squared area between the step function $F$ and the
diagonal $x\mapsto x$.

Set $V=U$ in \eqref{found:transformed-weak}:
\begin{equation}
 \overline u_\pi
 =\int_0^1b(y)|U'(y)|^2\,\mathrm dy
 +\sum_{j=1}^{N}\kappa_jU(y_j)^2.
 \label{found:general-test-U}
\end{equation}
Using $U'=\omega(F-y)$ and $b=1/\omega$,
\[
 b|U'|^2
 =\frac1\omega\bigl[\omega(F-y)\bigr]^2
 =\omega(F-y)^2.
\]
Using $U(y_j)=p_j/\kappa_j$,
\[
 \kappa_jU(y_j)^2=\frac{p_j^2}{\kappa_j}.
\]
Thus
\begin{equation}
 \boxed{
 \overline u_\pi
 =\sum_{j=1}^{N}\frac{p_j^2}{\kappa_j}
 +\int_0^1\omega(y)(F(y)-y)^2\,\mathrm dy.}
 \label{found:general-energy}
\end{equation}
This generalized energy identity is proved directly from the weak equation.
It is the exact starting point for the weighted-quantization proof.

\subsubsection{A complete one-trap example}

Take $N=1$, $x_1=c$, and $\kappa_1=K$. Conservation gives $p_1=1$, so
\[
 F(x)=
 \begin{cases}
 0,&0\leq x<c,\\
 1,&c\leq x\leq1.
 \end{cases}
\]
The flux law yields
\[
 u'(x)=
 \begin{cases}
 -x/D,&0<x<c,\\
 (1-x)/D,&c<x<1.
 \end{cases}
\]
Since $u(c)=p_1/K=1/K$, integration gives
\begin{equation}
 u(x)=
 \begin{cases}
 \displaystyle \frac1K+\frac{c^2-x^2}{2D},&0\leq x\leq c,\\[3mm]
 \displaystyle \frac1K+\frac{(1-c)^2-(1-x)^2}{2D},
 &c\leq x\leq1.
 \end{cases}
 \label{found:one-trap-u}
\end{equation}
For instance, on the left,
\[
 u(x)-u(c)=\int_c^x-\frac{s}{D}\,\mathrm ds
 =-\frac{x^2-c^2}{2D}.
\]

The energy identity gives
\begin{align}
 \overline u
 &=\frac1K+\frac1D
 \left(\int_0^c x^2\,\mathrm dx
 +\int_c^1(1-x)^2\,\mathrm dx\right) \notag\\
 &=\frac1K+\frac1D
 \left(\frac{c^3}{3}+\frac{(1-c)^3}{3}\right).
 \label{found:one-trap-objective}
\end{align}
Differentiate the spatial part:
\[
 \frac{\mathrm d}{\mathrm dc}
 \left(\frac{c^3+(1-c)^3}{3D}\right)
 =\frac{c^2-(1-c)^2}{D}
 =\frac{2c-1}{D}.
\]
It vanishes only at $c=1/2$, and the second derivative is $2/D>0$. Therefore
\begin{equation}
 \min\overline u
 =\frac1K+\frac1D\left(2\cdot\frac{(1/2)^3}{3}\right)
 =\frac1K+\frac1{12D}.
 \label{found:one-trap-optimum}
\end{equation}
This elementary case previews the stationary-average background formula
$1/(12DN^2)$ derived in the appendix.  It does not preview the main
worst-start correction $1/(8DN^2)$.

\subsubsection{Stationary density and conductance}

Let $\pi,a:[0,1]\to(0,\infty)$ be continuous and impose
\begin{equation}
 \int_0^1\pi(x)\,\mathrm dx=1.
 \label{found:pi-normalization}
\end{equation}
The function $\pi$ is the stationary probability density. The function $a$
is the conductance: it tells us how readily diffusive flux moves through each
location.

The reversible generator is
\begin{equation}
 \boxed{
 Lf(x)=\frac1{\pi(x)}\frac{\mathrm d}{\mathrm dx}
       \bigl(a(x)f'(x)\bigr).}
 \label{found:reversible-generator}
\end{equation}
If $a$ is differentiable, the product rule expands this as
\begin{align}
 Lf
 &=\frac1\pi\bigl(a'f'+af''\bigr)
 =\frac{a}{\pi}f''+\frac{a'}{\pi}f'.
 \label{found:generator-expanded}
\end{align}
In stochastic-differential-equation notation, the coefficient of $f''$ is
one half of the local variance rate. Thus the local variance rate is
$2a/\pi$, while $a'/\pi$ acts as drift. This expansion is explanatory; the
divergence form \eqref{found:reversible-generator} remains meaningful under
the continuity assumptions used in the theorem.

For constant reflected Brownian motion, take $\pi\equiv1$ and $a\equiv D$:
\[
 Lf=\frac11(Df')'=Df''.
\]
Thus the general notation contains the original model exactly.

\subsubsection{Why the model is reversible}

Define the stationary weighted inner product
\begin{equation}
 \langle f,g\rangle_\pi
 =\int_0^1f(x)g(x)\pi(x)\,\mathrm dx.
 \label{found:weighted-inner-product}
\end{equation}
Using the generator and integration by parts,
\begin{align*}
 \langle f,Lg\rangle_\pi
 &=\int_0^1f(x)
 \left[\frac1\pi(ag')'\right]\pi\,\mathrm dx\\
 &=\int_0^1f(x)(a(x)g'(x))'\,\mathrm dx\\
 &=\bigl[fag'\bigr]_0^1-\int_0^1a(x)f'(x)g'(x)\,\mathrm dx.
\end{align*}
Reflection means $ag'=0$ at $0$ and $1$, so
\begin{equation}
 \langle f,Lg\rangle_\pi
 =-\int_0^1af'g'\,\mathrm dx.
 \label{found:symmetry-one}
\end{equation}
Interchanging $f$ and $g$ does not change the integral, hence
\begin{equation}
 \langle f,Lg\rangle_\pi=\langle Lf,g\rangle_\pi.
 \label{found:reversibility}
\end{equation}
This symmetry is the analytic meaning of reversibility.

To check stationarity, set $f\equiv1$. Since $f'=0$,
\[
 \int_0^1Lg(x)\pi(x)\,\mathrm dx=0.
\]
Thus the expected infinitesimal change of $g$ under density $\pi$ is zero, so
$\pi(x)\,\mathrm dx$ is invariant.

The associated unkilled energy form is
\begin{equation}
 \mathcal E_0(f,g)=\int_0^1a(x)f'(x)g'(x)\,\mathrm dx.
 \label{found:dirichlet-form}
\end{equation}
Equation~\eqref{found:symmetry-one} says
$\langle f,-Lg\rangle_\pi=\mathcal E_0(f,g)$.

\subsection{The stationary-coordinate transformation, line by line}

The source on the right side of \eqref{found:general-weak} is $\pi(x)$ rather
than $1$. We make it uniform by measuring position in units of stationary
probability mass.

Define the cumulative stationary distribution
\begin{equation}
 P(x)=\int_0^x\pi(s)\,\mathrm ds.
 \label{found:P-definition}
\end{equation}
Because $\pi(x)>0$, $P$ is strictly increasing. Its endpoint values are
\[
 P(0)=0,\qquad
 P(1)=\int_0^1\pi(s)\,\mathrm ds=1.
\]
Thus $P$ maps $[0,1]$ bijectively onto $[0,1]$. Let
\begin{equation}
 X=P^{-1}
 \label{found:X-definition}
\end{equation}
be its inverse and introduce
\begin{equation}
 y=P(x),\qquad x=X(y).
 \label{found:y-coordinate}
\end{equation}
Since $P'(x)=\pi(x)$,
\begin{equation}
 \mathrm dy=\pi(x)\,\mathrm dx,
 \qquad
 \mathrm dx=\frac{\mathrm dy}{\pi(X(y))}.
 \label{found:differentials}
\end{equation}

Transform the unknown and a test function by defining
\begin{equation}
 U(y)=u(X(y)),\qquad V(y)=v(X(y)).
 \label{found:UV-definition}
\end{equation}
Equivalently, $u(x)=U(P(x))$ and $v(x)=V(P(x))$. The chain rule gives
\begin{equation}
 u'(x)=U'(P(x))\pi(x),\qquad
 v'(x)=V'(P(x))\pi(x).
 \label{found:UV-derivatives}
\end{equation}

Transform the derivative term without skipping a factor:
\begin{align}
 \int_0^1a(x)u'(x)v'(x)\,\mathrm dx
 &=\int_0^1a(x)
 \bigl[U'(P(x))\pi(x)\bigr]
 \bigl[V'(P(x))\pi(x)\bigr]\,\mathrm dx \notag\\
 &=\int_0^1a(x)\pi(x)^2
 U'(P(x))V'(P(x))\,\mathrm dx \notag\\
 &=\int_0^1a(X(y))\pi(X(y))^2
 U'(y)V'(y)\frac{\mathrm dy}{\pi(X(y))} \notag\\
 &=\int_0^1a(X(y))\pi(X(y))
 U'(y)V'(y)\,\mathrm dy.
 \label{found:transform-energy}
\end{align}
One factor of $\pi$ came from $u'$, a second came from $v'$, and one was
cancelled by $\mathrm dx=\mathrm dy/\pi$. Exactly one remains.

Define
\begin{equation}
 b(y)=a(X(y))\pi(X(y)),
 \qquad
 \omega(y)=\frac1{b(y)}
 =\frac1{a(X(y))\pi(X(y))}.
 \label{found:b-omega}
\end{equation}
Then \eqref{found:transform-energy} is
$\int_0^1b(y)U'(y)V'(y)\,\mathrm dy$.

The right-hand side transforms directly:
\begin{align}
 \int_0^1\pi(x)v(x)\,\mathrm dx
 &=\int_0^1\pi(x)V(P(x))\,\mathrm dx \notag\\
 &=\int_0^1V(y)\,\mathrm dy.
 \label{found:transform-source}
\end{align}

Define transformed trap positions
\begin{equation}
 y_j=P(x_j).
 \label{found:yj}
\end{equation}
Then $U(y_j)=u(X(P(x_j)))=u(x_j)$, and similarly $V(y_j)=v(x_j)$.
Therefore each point term becomes
\[
 \kappa_ju(x_j)v(x_j)=\kappa_jU(y_j)V(y_j).
\]
Combining the transformed terms gives
\begin{equation}
 \boxed{
 \int_0^1b(y)U'(y)V'(y)\,\mathrm dy
 +\sum_{j=1}^{N}\kappa_jU(y_j)V(y_j)
 =\int_0^1V(y)\,\mathrm dy.}
 \label{found:transformed-weak}
\end{equation}
The source is now uniform. All nonuniformity is compressed into $b$, or its
reciprocal weight $\omega$.

The objective also simplifies:
\begin{equation}
 \overline u_\pi
 =\int_0^1\pi(x)u(x)\,\mathrm dx
 =\int_0^1U(y)\,\mathrm dy.
 \label{found:transform-objective}

\subsection{The operator and its elementary meaning}

Fix a length \(L>0\), diffusivity \(D>0\), and ordered interior locations
\[
  0<x_1<x_2<\cdots<x_N<L.
\]
The strength of trap \(j\) is \(\kappa_j>0\).  For a sufficiently regular
real-valued function \(v\), define the quadratic energy
\begin{equation}
 \mathcal Q_{x,\kappa}[v]
 =D\int_0^L |v'(y)|^2\dd y
  +\sum_{j=1}^N\kappa_j|v(x_j)|^2.
 \label{eq:expanded-spectral-form}
\end{equation}
The first term charges rapid spatial variation.  The second charges a
function for being nonzero at a trap.  Both terms are nonnegative.

\begin{toolbox}{The Rayleigh--Ritz principle}
For a self-adjoint operator with compact resolvent and quadratic form
\(\mathcal Q\), its smallest eigenvalue is
\[
 \lambda_1=\min_{v\ne0}\frac{\mathcal Q[v]}{\int |v|^2}.
\]
Multiplying \(v\) by any nonzero constant multiplies numerator and
denominator by the same squared constant, so the quotient does not depend on
the normalization of \(v\).
\end{toolbox}

Applying this formula to \eqref{eq:expanded-spectral-form} gives
\begin{equation}
 \lambda_1(x,\kappa)=
 \min_{v\in H^1(0,L),\ v\ne0}
 \frac{D\int_0^L|v'(y)|^2\dd y
       +\sum_{j=1}^N\kappa_j|v(x_j)|^2}
      {\int_0^L|v(y)|^2\dd y}.
 \label{eq:expanded-Rayleigh}
\end{equation}
Here \(H^1(0,L)\) means that both \(v\) and its first weak derivative have
finite squared integrals.  In one dimension such functions have continuous
representatives, so the numbers \(v(x_j)\) are meaningful.

The formal operator behind the energy is
\begin{equation}
 H_{x,\kappa}=-D\frac{\dd^2}{\dd y^2}
       +\sum_{j=1}^N\kappa_j\delta_{x_j},
 \label{eq:expanded-H}
\end{equation}
with reflecting, or Neumann, endpoint conditions.  The symbol
\(\delta_{x_j}\) is the Dirac point mass already introduced in the
foundations chapter: integrating it against a continuous function evaluates
that function at \(x_j\).

\subsubsection{Start from the quadratic form}

For real functions $\phi\in H^1(0,L)$ define
\begin{equation}
 \mathfrak q[\phi]
 :=D\int_0^L|\phi'(x)|^2\dd x
 +\beta_0|\phi(0)|^2+\beta_L|\phi(L)|^2
 +\sum_{j=1}^N\kappa_j|\phi(x_j)|^2.
 \label{eq:exp-x16-form}
\end{equation}
All terms are nonnegative.  The principal eigenvalue is the minimum of the
Rayleigh quotient
\begin{equation}
 \lambda_1
 =\min_{\phi\ne0}
 \frac{\mathfrak q[\phi]}{\int_0^L|\phi|^2\dd x}.
 \label{eq:exp-x16-Rayleigh}
\end{equation}
This variational formula is the Rayleigh--Ritz principle.  Because at least
one interior strength is positive, $\lambda_1>0$.

The bilinear eigenvalue equation is
\begin{equation}
 D\int_0^L\phi'v'\dd x
 +\beta_0\phi(0)v(0)+\beta_L\phi(L)v(L)
 +\sum_j\kappa_j\phi(x_j)v(x_j)
 =\lambda\int_0^L\phi v\dd x.
 \label{eq:exp-x16-weak}
\end{equation}

\subsubsection{Integration by parts fixes both Robin signs}

Split the interval at the points $x_j$ and integrate by parts on every open
cell.  On a generic cell $[a,b]$,
\[
 D\int_a^b\phi'v'\dd x
 =-D\int_a^b\phi''v\dd x
 +D\phi'(b)v(b)-D\phi'(a)v(a).
\]
At $x=0$, the boundary contribution from the derivative integral is
$-D\phi'(0)v(0)$.  Adding the form term
$\beta_0\phi(0)v(0)$ gives
\[
 \{-D\phi'(0)+\beta_0\phi(0)\}v(0).
\]
Since $v(0)$ is arbitrary, its coefficient must be zero:
\begin{equation}
 \boxed{D\phi'(0)=\beta_0\phi(0).}
 \label{eq:exp-x16-left-Robin}
\end{equation}
At $x=L$, the derivative boundary contribution has the opposite sign,
$+D\phi'(L)v(L)$.  Therefore
\begin{equation}
 \boxed{D\phi'(L)=-\beta_L\phi(L).}
 \label{eq:exp-x16-right-Robin}
\end{equation}
The two signs are opposite because the outward directions at the two ends of
an interval are opposite.  Assigning the same sign at both ends would not
come from the quadratic form \eqref{eq:exp-x16-form}.

At an interior point $x_j$, the left- and right-cell boundary contributions
are, respectively,
\[
 +D\phi'(x_j-)v(x_j)
 \qquad\text{and}\qquad
 -D\phi'(x_j+)v(x_j).
\]
Adding the point term gives
\[
 \{D\phi'(x_j-)-D\phi'(x_j+)
 +\kappa_j\phi(x_j)\}v(x_j).
\]
Thus $\phi$ is continuous and its derivative satisfies
\begin{equation}
 \boxed{D\{\phi'(x_j+)-\phi'(x_j-)\}
 =\kappa_j\phi(x_j).}
 \label{eq:exp-x16-jump}
\end{equation}
Away from all point interactions, the remaining integral gives
\begin{equation}
 -D\phi''=\lambda\phi.
 \label{eq:exp-x16-free-equation}
\end{equation}

\subsubsection{What the stochastic statement does and does not say}

For the local-time-killed reflected diffusion, the survival semigroup is
\(e^{-tH_{x,\kappa}}\).  Let
\(\phi_1,\phi_2,\ldots\) be an orthonormal eigenbasis, ordered so that
\(0<\lambda_1<\lambda_2\leq\lambda_3\leq\cdots\), and choose
\(\phi_1>0\).  If the initial probability density is a nonzero function
\(r\geq0\) in \(L^2(0,L)\), then the spectral expansion gives
\begin{align}
 \Pr_r(\tau>t)
 &=\langle r,e^{-tH_{x,\kappa}}\mathbf1\rangle\notag\\
 &=\sum_{n=1}^{\infty}e^{-\lambda_nt}
   \langle r,\phi_n\rangle\langle\phi_n,\mathbf1\rangle.
 \label{eq:expanded-survival-series}
\end{align}
The coefficient of the first term is
\[
 c_1=\langle r,\phi_1\rangle\langle\phi_1,\mathbf1\rangle>0,
\]
because \(r\) is nonnegative and nonzero while \(\phi_1\) is strictly
positive.  Cauchy--Schwarz and Parseval bound the remainder by
\begin{align*}
 \left|\sum_{n\geq2}e^{-\lambda_nt}
 \langle r,\phi_n\rangle\langle\phi_n,\mathbf1\rangle\right|
 &\leq e^{-\lambda_2t}
 \left(\sum_{n\geq2}|\langle r,\phi_n\rangle|^2\right)^{1/2}
 \left(\sum_{n\geq2}|\langle\mathbf1,\phi_n\rangle|^2\right)^{1/2}\\
 &\leq e^{-\lambda_2t}\lVert r\rVert_2\sqrt L.
\end{align*}
Consequently,
\begin{equation}
 \Pr_r(\tau>t)=c_1e^{-\lambda_1t}+O(e^{-\lambda_2t}),
 \qquad c_1>0.
 \label{eq:expanded-survival-asymptotic}
\end{equation}
A point start can be handled after any positive smoothing time by the heat
kernel and has the same exponential rate.
This is a \emph{long-time asymptotic}.  Maximizing \(\lambda_1\) does not by
itself prove that one design has smaller survival probability at every finite
time, and it does not follow from the mean-lifetime theorem.

\begin{toolbox}{Quotient rule}
If \(g\) and \(h\) are differentiable and \(h\ne0\), then
\[
 \left(\frac gh\right)'=\frac{g'h-gh'}{h^2}.
\]
\end{toolbox}

Use \(g=\phi'\) and \(h=k\phi\).  Since \(k\) is constant,
\(g'=\phi''\) and \(h'=k\phi'\).  Therefore
\[
 p'
 =\frac{\phi''(k\phi)-\phi'(k\phi')}{k^2\phi^2}
 =\frac{k\phi\phi''-k(\phi')^2}{k^2\phi^2}.
\]
Cancel one factor \(k\):
\[
 p'=\frac{\phi\phi''-(\phi')^2}{k\phi^2}.
\]
Equation \eqref{eq:expanded-free-ode} says \(\phi''=-k^2\phi\), hence
\[
 p'=\frac{-k^2\phi^2-(\phi')^2}{k\phi^2}
 =-k-\frac{(\phi')^2}{k\phi^2}.
\]
By \eqref{eq:expanded-p-ratio},
\((\phi')^2/(k^2\phi^2)=p^2\), so
\begin{equation}
 p'=-k(1+p^2).
 \label{eq:expanded-Riccati}
\end{equation}

Now define the principal angle
\begin{equation}
 \theta(y)=\arctan p(y)
 =\arctan\!\left(\frac{\phi'(y)}{k\phi(y)}\right),
 \qquad -\frac\pi2<\theta(y)<\frac\pi2.
 \label{eq:expanded-theta}
\end{equation}

\begin{toolbox}{Derivative of arctangent and the chain rule}
\[
 \frac{\dd}{\dd z}\arctan z=\frac1{1+z^2},
 \qquad
 \frac{\dd}{\dd y}\arctan(p(y))=\frac{p'(y)}{1+p(y)^2}.
\]
\end{toolbox}

Substitute \eqref{eq:expanded-Riccati}:
\begin{equation}
 \theta'(y)=\frac{-k(1+p^2)}{1+p^2}=-k.
 \label{eq:expanded-theta-slope}

\begin{toolbox}{antiderivative of the constant function $1$}
If $F'(q)=1$, then $F(q)=q+C$ for one constant $C$.
Writing $C=-\alpha$ is only a convenient renaming.
\end{toolbox}

Apply this to \eqref{eq:exp-x12-source-ode}.  There is a real number
$\alpha$ such that
\begin{equation}
 \frac{y'(q)}{\Omega(q)}=q-\alpha,
 \qquad
 \boxed{\displaystyle y'(q)=\Omega(q)(q-\alpha).}
 \label{eq:exp-x12-yprime}
\end{equation}

\begin{toolbox}{strict convexity test}
If a twice differentiable function satisfies $f''(x)>0$ throughout an
interval, then $f'$ is strictly increasing and $f$ is strictly convex.
It has at most one critical point, and any critical point is its unique
global minimizer.
\end{toolbox}

The minimizer is not at an endpoint.  Indeed, with $A,B$ from
\eqref{eq:exp-x12-AB}, formula \eqref{eq:exp-x12-Phiprime} gives
\begin{equation}
 \frac{\Phi'(0)}m=-A-B<0,
 \qquad
 \frac{\Phi'(1)}m=2B-A>0.
 \label{eq:exp-x12-end-derivatives}
\end{equation}
Because $\Phi'$ is continuous and strictly increasing, the Intermediate
Value Theorem gives exactly one
\begin{equation}
