\begin{toolbox}{weighted Cauchy--Schwarz inequality}
For nonnegative weights $w_i$ with $W=\sum_iw_i>0$,
\[
 \sum_iw_ix_i^2\geq\frac{(\sum_iw_ix_i)^2}{W}.
\]
It follows from ordinary Cauchy--Schwarz applied to the vectors
$(\sqrt{w_i}x_i)$ and $(\sqrt{w_i})$.  Equality holds exactly when all
$x_i$ with positive weight are equal.
\end{toolbox}

Apply this with $w_i=\kappa_v$, $x_i=u(v)$, use
\eqref{eq:exp-x12-flux-balance}, and recall $\sum_v\kappa_v=K$:
\begin{equation}
 \sum_v\kappa_vu(v)^2
 \geq\frac{(\sum_v\kappa_vu(v))^2}{K}
 =\frac{V^2}{K}.
 \label{eq:exp-x12-reaction-cauchy}
